/* ===================== BÀI 18 · ASCII, UTF-8, UTF-16, BOM ===================== */
/* Bài 18 · ASCII, UTF-8, UTF-16, BOM (CM02.04) — sinh bởi tools/author/maytinh/m18.py, không sửa tay.
   Phòng mô phỏng từng bước và bài tập chấm tự động; phần chữ bài học ở lesson.html (nội dung bảo vệ). */
makeMtLab(document.getElementById("lab-l18"),{id:"l18",scenarios:[{"label": "Ví dụ: Bảng ASCII cơ bản", "note": "Chữ hoa, chữ thường lệch 0x20; '0' là 0x30.", "steps": [{"t": "ASCII: 128 ký tự, mã 0–127", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Ký tự<\/th><th scope=\"col\">Hệ 10<\/th><th scope=\"col\">Hex<\/th><th scope=\"col\">Nhị phân<\/th><\/tr><\/thead><tbody><tr><td>'0'<\/td><td>48<\/td><td>30<\/td><td>0011 0000<\/td><\/tr><tr><td>'A'<\/td><td>65<\/td><td>41<\/td><td>0100 0001<\/td><\/tr><tr><td>'a'<\/td><td>97<\/td><td>61<\/td><td>0110 0001<\/td><\/tr><tr><td>dấu cách<\/td><td>32<\/td><td>20<\/td><td>0010 0000<\/td><\/tr><\/tbody><\/table>", "say": "<p>ASCII (chuẩn Mỹ, 1963) dùng 7 bit, gồm chữ Latinh không dấu, chữ số, dấu câu và các mã điều khiển (xuống dòng = 10, …).<\/p>"}, {"t": "Chữ hoa và chữ thường lệch đúng 0x20", "html": "<p class=\"mt-calc\">'A' = 0x41, 'a' = 0x61 → khác nhau đúng bit 5 (giá trị 32)<\/p>", "ask": {"q": "'B' = 0x42. Mã của 'b' là gì?", "o": ["0x43", "0x62", "0x22"], "a": 1}}, {"t": "Chữ số '7' không phải số 7", "html": "<p class=\"mt-calc\">'7' = 0x37 = 55 · giá trị số = 55 − 48 = 7<\/p>", "say": "<p>Ký tự chữ số và giá trị số là hai thứ khác nhau; đọc dữ liệu văn bản từ cổng nối tiếp phải đổi bằng cách trừ 48 (0x30).<\/p>"}]}, {"label": "Ví dụ: 'đ' sang UTF-8 (2 byte)", "note": "Chia 11 bit thành 5 + 6, thêm tiền tố 110 và 10.", "steps": [{"t": "'đ' = U+0111", "html": "<p class=\"mt-calc\">Mã điểm (code point) U+0111 = 273 · cần 9 bit có nghĩa → dạng UTF-8 2 byte<\/p>", "say": "<p>Bảng chọn số byte: U+0000–007F: 1 byte; U+0080–07FF: 2 byte; U+0800–FFFF: 3 byte; U+10000–10FFFF: 4 byte.<\/p>"}, {"t": "Chia 11 bit thành 5 + 6", "html": "<p class=\"mt-calc\">U+0111 = 00100010001₂ → 00100 | 010001<\/p>"}, {"t": "Thêm tiền tố: 11000100 10010001", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Byte<\/th><th scope=\"col\">Tiền tố<\/th><th scope=\"col\">Bit dữ liệu<\/th><th scope=\"col\">Hex<\/th><\/tr><\/thead><tbody><tr><td>1<\/td><td>110<\/td><td>00100<\/td><td class=\"new\">C4<\/td><\/tr><tr><td>2<\/td><td>10<\/td><td>010001<\/td><td class=\"new\">91<\/td><\/tr><\/tbody><\/table>", "ask": {"q": "Các byte tiếp theo (sau byte đầu) trong UTF-8 luôn bắt đầu bằng tiền tố nào?", "o": ["0", "10", "110"], "a": 1}}, {"t": "'đ' trong UTF-8: C4 91", "html": "<p class=\"mt-calc\"><b>C4 91<\/b> (2 byte)<\/p>"}]}, {"label": "Ví dụ: 'ệ' sang UTF-8 (3 byte)", "note": "Chia 16 bit thành 4 + 6 + 6.", "steps": [{"t": "'ệ' = U+1EC7", "html": "<p class=\"mt-calc\">Mã điểm (code point) U+1EC7 = 7879 · cần 13 bit có nghĩa → dạng UTF-8 3 byte<\/p>", "say": "<p>Bảng chọn số byte: U+0000–007F: 1 byte; U+0080–07FF: 2 byte; U+0800–FFFF: 3 byte; U+10000–10FFFF: 4 byte.<\/p>"}, {"t": "Chia 16 bit thành 4 + 6 + 6", "html": "<p class=\"mt-calc\">U+1EC7 = 0001111011000111₂ → 0001 | 111011 | 000111<\/p>"}, {"t": "Thêm tiền tố: 11100001 10111011 10000111", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Byte<\/th><th scope=\"col\">Tiền tố<\/th><th scope=\"col\">Bit dữ liệu<\/th><th scope=\"col\">Hex<\/th><\/tr><\/thead><tbody><tr><td>1<\/td><td>1110<\/td><td>0001<\/td><td class=\"new\">E1<\/td><\/tr><tr><td>2<\/td><td>10<\/td><td>111011<\/td><td class=\"new\">BB<\/td><\/tr><tr><td>3<\/td><td>10<\/td><td>000111<\/td><td class=\"new\">87<\/td><\/tr><\/tbody><\/table>", "ask": {"q": "Các byte tiếp theo (sau byte đầu) trong UTF-8 luôn bắt đầu bằng tiền tố nào?", "o": ["0", "10", "110"], "a": 1}}, {"t": "'ệ' trong UTF-8: E1 BB 87", "html": "<p class=\"mt-calc\"><b>E1 BB 87<\/b> (3 byte)<\/p>"}]}, {"label": "Ví dụ: UTF-16 và cặp thay thế", "note": "Ký tự ngoài U+FFFF cần 4 byte trong UTF-16.", "steps": [{"t": "UTF-16: mỗi đơn vị 16 bit", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Ký tự<\/th><th scope=\"col\">Mã điểm<\/th><th scope=\"col\">UTF-16 (big-endian)<\/th><th scope=\"col\">Số byte<\/th><\/tr><\/thead><tbody><tr><td>A<\/td><td>U+0041<\/td><td>00 41<\/td><td>2<\/td><\/tr><tr><td>ệ<\/td><td>U+1EC7<\/td><td>1E C7<\/td><td>2<\/td><\/tr><\/tbody><\/table>", "say": "<p>Ký tự trong khoảng U+0000–FFFF (trừ vùng thay thế) dùng một đơn vị 16 bit.<\/p>"}, {"t": "Ký tự ngoài U+FFFF cần cặp thay thế", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Ký tự<\/th><th scope=\"col\">Mã điểm<\/th><th scope=\"col\">UTF-16 (big-endian)<\/th><th scope=\"col\">UTF-8<\/th><\/tr><\/thead><tbody><tr><td>😀 (mặt cười)<\/td><td>U+1F600<\/td><td class=\"new\">D8 3D DE 00<\/td><td>F0 9F 98 80<\/td><\/tr><\/tbody><\/table>", "ask": {"q": "Ký tự U+1F600 trong UTF-16 cần bao nhiêu byte?", "o": ["2", "3", "4"], "a": 2}, "say": "<p>Ký tự ngoài mặt phẳng cơ bản được mã bằng cặp thay thế: hai đơn vị 16 bit (4 byte). Vì vậy “độ dài chuỗi” tính theo đơn vị UTF-16 (như trong C#, Java, JavaScript) có thể khác số ký tự.<\/p>"}]}, {"label": "Ví dụ: BOM ở đầu tệp", "note": "Nhận biết UTF-8, UTF-16 LE, UTF-16 BE qua byte đầu.", "steps": [{"t": "BOM là ký tự U+FEFF đặt ở đầu tệp", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Bảng mã<\/th><th scope=\"col\">Byte BOM<\/th><\/tr><\/thead><tbody><tr><td>UTF-8<\/td><td>EF BB BF<\/td><\/tr><tr><td>UTF-16 big-endian<\/td><td>FE FF<\/td><\/tr><tr><td>UTF-16 little-endian<\/td><td>FF FE<\/td><\/tr><\/tbody><\/table>", "say": "<p>BOM cho biết thứ tự byte của UTF-16 (Bài 20). Với UTF-8, thứ tự byte không có nghĩa; BOM chỉ là dấu hiệu “đây là UTF-8” và không bắt buộc.<\/p>"}, {"t": "Tệp UTF-16 LE chứa 'A': FF FE 41 00", "html": "<p class=\"mt-calc\">BOM FF FE → little-endian → 41 00 là U+0041 'A'<\/p>", "ask": {"q": "Tệp bắt đầu bằng FE FF. Đó là gì?", "o": ["BOM của UTF-16 big-endian", "BOM của UTF-8", "Chữ 'þÿ'"], "a": 0}}, {"t": "Bẫy: BOM UTF-8 làm hỏng dòng đầu ở chương trình không chờ nó", "html": "<p class=\"mt-calc\">EF BB BF + 'id,ten' → chương trình đọc cột đầu thành '\\uFEFFid' thay vì 'id'<\/p>", "say": "<p>Một số phần mềm thêm BOM khi lưu UTF-8, số khác không hiểu nó. Khi viết chương trình đọc tệp, hãy bỏ BOM nếu có.<\/p>"}]}, {"label": "Bẫy: Số byte khác số ký tự", "note": "'Việt': 4 ký tự, 6 byte; dạng NFD 8 byte.", "steps": [{"t": "'Việt': 4 ký tự", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Ký tự<\/th><th scope=\"col\">V<\/th><th scope=\"col\">i<\/th><th scope=\"col\">ệ<\/th><th scope=\"col\">t<\/th><\/tr><\/thead><tbody><tr><td>UTF-8<\/td><td>56<\/td><td>69<\/td><td class=\"new\">E1 BB 87<\/td><td>74<\/td><\/tr><\/tbody><\/table>", "say": "<p>Chữ không dấu 1 byte, chữ có dấu tiếng Việt thường 2 hoặc 3 byte.<\/p>"}, {"t": "Nhưng 6 byte trong UTF-8", "html": "<p class=\"mt-calc\">1 + 1 + 3 + 1 = <b>6 byte<\/b><\/p>", "ask": {"q": "Chuỗi 'Việt' (dạng dựng sẵn) dài bao nhiêu byte trong UTF-8?", "o": ["4", "6", "8"], "a": 1}}, {"t": "Cùng chữ, dạng tổ hợp: 8 byte", "html": "<p class=\"mt-calc\">Dạng tổ hợp (NFD): ệ = e + dấu nặng U+0323 + dấu mũ U+0302 → 'Việt' có 6 mã điểm, 8 byte<\/p>", "say": "<p>Unicode cho phép viết một chữ có dấu dạng dựng sẵn (NFC) hoặc chữ gốc kèm dấu tổ hợp (NFD). Hai chuỗi trông giống hệt nhưng byte khác nhau: phải chuẩn hóa (thường về NFC) trước khi so sánh, tìm kiếm, đếm độ dài.<\/p>"}]}, {"label": "Lỗi: Chữ vỡ khi đọc sai bảng mã", "note": "Byte UTF-8 đọc bằng Windows-1252.", "steps": [{"t": "Tệp lưu bằng UTF-8: 'Việt' = 56 69 E1 BB 87 74", "html": "<p class=\"mt-calc\">Byte trên đĩa: 56 69 E1 BB 87 74<\/p>", "say": "<p>Một phần mềm cũ mở tệp nhưng giả định bảng mã Windows-1252 (mỗi byte một ký tự).<\/p>"}, {"t": "Đọc nhầm bảng mã: 'Viá»‡t'", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Byte<\/th><th scope=\"col\">56<\/th><th scope=\"col\">69<\/th><th scope=\"col\">E1<\/th><th scope=\"col\">BB<\/th><th scope=\"col\">87<\/th><th scope=\"col\">74<\/th><\/tr><\/thead><tbody><tr><td>Windows-1252<\/td><td>V<\/td><td>i<\/td><td class=\"bad\">á<\/td><td class=\"bad\">»<\/td><td class=\"bad\">‡<\/td><td>t<\/td><\/tr><\/tbody><\/table>", "ask": {"q": "Chữ bị “vỡ” thành 'Viá»‡t'. Nguyên nhân là gì?", "o": ["Tệp bị hỏng byte", "Byte UTF-8 bị đọc bằng bảng mã khác", "Font chữ thiếu dấu"], "a": 1}}, {"t": "Sửa: khai báo và đọc đúng bảng mã", "html": "<p class=\"mt-calc\">Mở tệp với mã UTF-8; khi trao đổi dữ liệu (CSV, giao thức, cơ sở dữ liệu) ghi rõ “UTF-8” trong đặc tả<\/p>", "say": "<p>Hiện tượng chữ vỡ này có tên mojibake. Byte không hỏng; chỉ cách đọc sai. Đừng “sửa” bằng cách gõ lại dữ liệu.<\/p>"}]}]});
makeMtEx(document.getElementById("ex-l18"),"l18",[{"kind": "num", "t": "Mã ASCII và mã điểm", "d": "<p>Ghi giá trị ở hệ 10.<\/p>", "items": [{"q": "Mã ASCII của 'A'", "a": 65}, {"q": "Mã ASCII của 'a'", "a": 97}, {"q": "Mã ASCII của ký tự '0'", "a": 48}, {"q": "Mã điểm của 'đ' (U+0111) ở hệ 10", "a": 273}], "hints": ["'A' = 0x41.", "Chữ thường = chữ hoa + 0x20 (32).", "U+0111 = 1 × 256 + 1 × 16 + 1."], "why": "'A' = 65, 'a' = 97, '0' = 48, U+0111 = 273."}, {"kind": "num", "t": "Đếm byte", "d": "<p>Các chuỗi viết ở dạng dựng sẵn (NFC). Ghi số byte.<\/p>", "items": [{"q": "'Việt' trong UTF-8", "a": 6}, {"q": "'đ' trong UTF-8", "a": 2}, {"q": "'Xin chào Việt Nam' trong UTF-8 (có 3 dấu cách)", "a": 20}, {"q": "'A' trong UTF-16 (không BOM)", "a": 2}, {"q": "😀 (U+1F600) trong UTF-8", "a": 4}], "hints": ["Chữ không dấu, chữ số, dấu cách: 1 byte trong UTF-8.", "U+0080–07FF: 2 byte (ví dụ à = U+00E0, đ); U+0800–FFFF: 3 byte (ví dụ ệ = U+1EC7).", "'Xin chào Việt Nam': 'à' 2 byte, 'ệ' 3 byte, còn lại 1 byte."], "why": "'Việt' = 1 + 1 + 3 + 1 = 6; 'đ' = 2; 'Xin chào Việt Nam' có 17 ký tự, 'à' thêm 1 byte và 'ệ' thêm 2 byte → 20 byte; UTF-16 'A' = 2; emoji 4 byte."}, {"kind": "pick", "t": "Nhận biết bảng mã qua byte đầu tệp", "d": "<p>Chọn bảng mã phù hợp với các byte đầu tiên của tệp văn bản.<\/p>", "cats": ["UTF-8 có BOM", "UTF-16 little-endian", "UTF-16 big-endian", "UTF-8 hoặc ASCII không BOM"], "items": [{"q": "EF BB BF 69 64", "a": 0}, {"q": "FF FE 41 00", "a": 1}, {"q": "FE FF 00 41", "a": 2}, {"q": "41 42 43", "a": 3}, {"q": "56 69 E1 BB 87 74", "a": 3}], "hints": ["BOM của UTF-8 là EF BB BF.", "FF FE: byte thấp trước (little-endian); FE FF: byte cao trước.", "Không có BOM, byte E1 BB 87 là một chữ 3 byte của UTF-8."], "why": "EF BB BF là BOM UTF-8; FF FE là UTF-16 LE; FE FF là UTF-16 BE; 41 42 43 là ASCII (cũng là UTF-8); 56 69 E1 BB 87 74 là 'Việt' UTF-8 không BOM."}]);

makeQuiz("quiz18","score18",[{"q": "'ệ' (U+1EC7) cần bao nhiêu byte trong UTF-8?", "o": ["1", "2", "3", "4"], "a": 2, "e": "U+0800–FFFF dùng 3 byte: E1 BB 87."}, {"q": "Trong UTF-8, byte nào sau đây chắc chắn là byte tiếp nối (không phải byte đầu của ký tự)?", "o": ["0x41", "0xBB", "0xE1", "0xC4"], "a": 1, "e": "0xBB = 1011 1011, bắt đầu bằng 10: byte tiếp nối. 0xE1, 0xC4 là byte đầu; 0x41 là ký tự 1 byte."}, {"q": "Vì sao chuỗi 'Việt' có độ dài 4 ký tự nhưng 6 byte UTF-8?", "o": ["Vì UTF-8 luôn dùng 1,5 byte mỗi ký tự", "Vì có BOM", "Vì máy tính lưu sai", "Vì 'ệ' cần 3 byte, các chữ còn lại 1 byte"], "a": 3, "e": "Mỗi ký tự dùng 1–4 byte tùy mã điểm."}, {"q": "Tệp bắt đầu bằng FF FE. Điều này cho biết gì?", "o": ["Tệp UTF-16 little-endian", "Tệp UTF-8", "Tệp bị hỏng", "Tệp ảnh"], "a": 0, "e": "FF FE là BOM U+FEFF viết theo thứ tự little-endian."}, {"q": "Văn bản UTF-8 'Việt' hiện thành 'Viá»‡t'. Cách xử lý đúng là gì?", "o": ["Gõ lại toàn bộ dữ liệu", "Đổi font chữ", "Mở lại tệp với bảng mã UTF-8", "Xóa các ký tự lạ"], "a": 2, "e": "Byte vẫn đúng; chỉ bị đọc bằng bảng mã khác (Windows-1252). Đọc lại đúng bảng mã là đủ."}]);

